ruleBookInfo.init:
@js:
(function(){
  var d = JSON.parse(result);
  return JSON.stringify({
    name: d.title || '',
    author: (d.author || '') + '｜播音:' + (d.teller || ''),
    cover: d.cover_url || '',
    intro: d.synopsis || '',
    kind: (d.type || '') + '/' + (d.cat || ''),
    lastChapter: '',
    tocUrl: 'https://laopaoaappi.oobyvy.vip/api/h5/listening/chapters/' + d.id
  });
})()

ruleContent.content:
@js:
(function(){
  var m = String(java.ruleUrl || '').match(/album\/(\d+)\?chapter_idx=(\d+)/);
  if(!m) return '';
  var albumId = m[1], idx = m[2];
  var resp = java.ajax('https://laopaoaappi.oobyvy.vip/api/h5/listening/play', {
    method: 'POST',
    body: JSON.stringify({album_id: albumId, chapter_idx: parseInt(idx)}),
    headers: {'Content-Type': 'application/json', 'Origin': 'https://tingyou.fm', 'Referer': 'https://tingyou.fm/listening'}
  });
  try{
    var j = JSON.parse(resp);
    return j.play_url || '';
  }catch(e){ return ''; }
})()

ruleToc.chapterList:
@js:
(function(){
  try{ book.type = 32; }catch(e){}
  var d = JSON.parse(result);
  var chs = d.chapters || [];
  var out = [];
  for (var i=0;i<chs.length;i++){
    var c = chs[i];
    var idx = c.index || (i+1);
    out.push({
      name: c.title || ('第' + idx + '集'),
      url: 'https://laopaoaappi.oobyvy.vip/api/h5/listening/album/' + (d.id||'') + '?chapter_idx=' + idx,
      isVolume: false
    });
  }
  return JSON.stringify(out);
})()
